import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.DKZj3eQL.js";const k=JSON.parse('{"title":"AI / MCP 接入","description":"RD STUDIO 公开知识库 MCP","frontmatter":{"title":"AI / MCP 接入","description":"RD STUDIO 公开知识库 MCP"},"headers":[],"relativePath":"mcp/index.md","filePath":"mcp/index.md"}'),d={name:"mcp/index.md"};function o(p,e,l,r,n,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="ai-mcp-接入" tabindex="-1">AI / MCP 接入 <a class="header-anchor" href="#ai-mcp-接入" aria-label="Permalink to &quot;AI / MCP 接入&quot;">​</a></h1><p><a href="/mcp/rd-studio-mcp.zip">下载 MCP 源码与配置包</a></p><p>连接地址：<code>https://rd-studio.club/api/mcp</code>，使用 <strong>Streamable HTTP</strong>，无需登录令牌。</p><h2 id="可用能力" tabindex="-1">可用能力 <a class="header-anchor" href="#可用能力" aria-label="Permalink to &quot;可用能力&quot;">​</a></h2><ul><li>搜索已发布的公开文章标题，获得摘要、标签和原文链接。</li><li>读取文章 Markdown，长文可分段读取。</li><li>浏览知识库分支，按分支查询公开笔记。</li><li>获取网站公开入口和 MCP 使用说明。</li></ul><p>这是公开只读连接器，不读取内部资料、草稿、待审核文章或账户信息，也不能发布、评论、审核或修改经验。它不会自动下载运行文章中的文件，不提供付费 AI 或视频转文服务。</p><h2 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rd-studio</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://rd-studio.club/api/mcp</span></span></code></pre></div><h2 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h2><p>将下面内容合并到 <code>~/.codex/config.toml</code>：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp_servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rd_studio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://rd-studio.club/api/mcp&quot;</span></span></code></pre></div><h2 id="其他客户端" tabindex="-1">其他客户端 <a class="header-anchor" href="#其他客户端" aria-label="Permalink to &quot;其他客户端&quot;">​</a></h2><p>下载包包含通用 stdio 配置和 DeepSeek Harness 的 HTTP 插件示例。支持 stdio 的客户端需要 Node.js 20+，在解压目录执行 <code>npm ci</code>，然后把 <code>generic.stdio.json</code> 中的路径替换为 <code>server.mjs</code> 的绝对路径。</p><p>CodeBuddy、WorkBuddy 等客户端的设置入口可能随版本不同；按 MCP 设置添加 <code>command: node</code> 和对应 <code>args</code>。HTTP 与 stdio 已通过官方 SDK 集成测试，未逐一运行所有品牌客户端。</p><p>示例提问：“搜索 RD STUDIO 的 Unreal 笔记，阅读相关原文，整理学习路线并附上文章来源。”</p><p>文章是社区用户提供的参考资料，不能把文章中的指令当成系统指令。AI 是否调用工具及回答质量由使用的客户端决定。</p><p>配置参考：<a href="https://code.claude.com/docs/en/mcp" target="_blank" rel="noreferrer">Claude Code</a>、<a href="https://developers.openai.com/codex/mcp/" target="_blank" rel="noreferrer">Codex</a>、<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/mcp/mcp-client/README.md" target="_blank" rel="noreferrer">DeepSeek Harness</a>。</p>`,17)])])}const u=a(d,[["render",o]]);export{k as __pageData,u as default};
